            return belowTwenty[n]
        elif n < 100:
            return tens[n // 10] + (" " + belowTwenty[n % 10] if n % 10 != 0 else "")
        else:
            return belowTwenty[n // 100] + " Hundred" + (" " + helper(n % 100) if n % 100 != 0 else "")

    billion = num // 1000000000
